    addQ(1, 2, 3, 'Babür Devleti hükümdarı Şah Cihan tarafından eşi Mümtaz Mahal anısına Hindistan\'ın Agra kentinde yaptırılan şaheser hangisidir?', 'Tac Mahal', 'Moti Mescidi', 'Kızıl Kale', 'Hümayun Türbesi', 'Lahor Kalesi', 'A', 'Tac Mahal beyaz mermerden yapılmış dünyanın en görkemli anıt mezarlarından biridir.');
    addQ(1, 2, 3, 'İlk Türk denizcisi kabul edilen ve 1081 yılında İzmir merkezli ilk Türk beyliğini kuran komutan kimdir?', 'Çaka Bey', 'Umur Bey', 'Karesi Bey', 'Saruhan Bey', 'Aydınoğlu Mehmet Bey', 'A', 'Çaka Bey 1081\'de ilk donanmayı kurmuş ve Türk Deniz Kuvvetleri\'nin kuruluş yılı olmuştur.');
    addQ(1, 2, 3, 'Anadolu\'da kurulan ilk Türk beyliklerinden hangisi Divriği Ulu Camii ve Darüşşifası\'nı inşa etmiş ve UNESCO mirasına girmiştir?', 'Mengücekliler', 'Danişmentliler', 'Artuklular', 'Saltuklular', 'Çaka Beyliği', 'A', 'Sivas Divriği Ulu Camii Mengücekliler döneminde Ahmet Şah ve Melike Turan tarafından yaptırılmıştır.');
    addQ(1, 2, 3, 'Anadolu Selçuklu Devleti\'nin ilk başkenti neresiydi ve I. Haçlı Seferi sonucu başkent nereye taşınmıştır?', 'İznik - Konya', 'Konya - Sivas', 'Kayseri - İznik', 'Bursa - Edirne', 'İznik - Alanya', 'A', 'Kutalmışoğlu Süleyman Şah İznik\'i başkent yapmış, I. Haçlı Seferi\'nde İznik düşünce başkent Konya\'ya taşınmıştır.');
    addQ(1, 2, 3, '1176 Miryokefalon Savaşı\'nın Türk tarihindeki en temel önemi aşağıdakilerden hangisidir?', 'Anadolu\'nun kesin olarak Türk yurdu olduğunun tescillenmesi', 'Bizans İmparatorluğu\'nun yıkılması', 'İlk beyliklerin kurulması', 'Haçlı seferlerinin tamamen bitmesi', 'Kösedağ yenilgisinin yaşanması', 'A', 'Miryokefalon Zaferi ile Bizans savunmaya çekilmiş, Anadolu\'nun tapusu Türklerin eline geçmiştir.');

