    // Level 1: Temel Olaylar
    addQ(1, 3, 1, 'Osmanlı Devleti ile Bizans arasında yapılan tarihteki ilk savaş hangisidir?', 'Koyunhisar (Bafeus) Savaşı', 'Maltepe Savaşı', 'Sırpsındığı Savaşı', 'I. Kosova Savaşı', 'Varna Savaşı', 'A', '1302 Koyunhisar Savaşı Osman Gazi döneminde Bizans tekfurlarına karşı kazanılmıştır.');
    addQ(1, 3, 1, 'Osmanlı Devleti\'nde Rumeli\'ye ilk geçiş hangi kalenin fethi ve Çimpe Kalesi\'nin üs olarak alınmasıyla gerçekleşmiştir?', 'Çimpe Kalesi', 'Gelibolu Kalesi', 'Kilitbahir', 'Rumeli Hisarı', 'Belgrad Kalesi', 'A', 'Orhan Bey döneminde Bizans\'a yardım karşılığı 1353\'te Çimpe Kalesi alınarak Rumeli\'ye adım atılmıştır.');
    addQ(1, 3, 1, 'Osmanlı Devleti\'nde Divan teşkilatı, vezirlik makamı ve ilk düzenli ordu (Yaya ve Müsellem) kimin döneminde kurulmuştur?', 'Orhan Bey', 'Osman Gazi', 'I. Murad', 'Yıldırım Bayezid', 'II. Mehmed', 'A', 'Orhan Bey beylikten devlete geçişi sağlayan tüm temel teşkilatlanmaları başlatmıştır.');
    addQ(1, 3, 1, 'Osmanlı Devleti\'nde padişah unvanını ve Sultan unvanını ilk kullanan hükümdarlar kimlerdir?', 'I. Murad - Orhan Bey', 'Osman Gazi - Orhan Bey', 'Yıldırım Bayezid - Çelebi Mehmed', 'Fatih - Yavuz', 'II. Murad - I. Murad', 'A', 'Orhan Bey Sultan unvanını sikkeye bastıran, I. Murad ise Padişah unvanını kullanan hükümdardır.');
    addQ(1, 3, 1, 'İstanbul\'u fethederek Orta Çağ\'ı kapatıp Yeni Çağ\'ı açan Osmanlı padişahı kimdir?', 'II. Mehmed (Fatih)', 'Yavuz Sultan Selim', 'Kanuni Sultan Süleyman', 'I. Murad', 'Yıldırım Bayezid', 'A', '29 Mayıs 1453\'te İstanbul\'u fetheden II. Mehmed "Fatih" unvanını almıştır.');
    addQ(1, 3, 1, 'Ankara Savaşı\'nda (1402) Timur\'a esir düşen ve Osmanlı\'nın Fetret Devri\'ne girmesine sebep olan padişah kimdir?', 'I. Bayezid (Yıldırım)', 'I. Murad', 'Çelebi Mehmed', 'II. Murad', 'Orhan Gazi', 'A', 'Yıldırım Bayezid Ankara Savaşı sonrası esir düşmüş ve 11 yıllık Fetret Devri başlamıştır.');
    addQ(1, 3, 1, 'Fetret Devri\'ne son vererek devleti yıkılmaktan kurtardığı için Osmanlı\'nın ikinci kurucusu sayılan padişah kimdir?', 'I. Mehmed (Çelebi)', 'II. Murad', 'Fatih Sultan Mehmed', 'II. Bayezid', 'Yavuz Sultan Selim', 'A', 'Çelebi Mehmed kardeşlerini saf dışı bırakarak birliği yeniden tesis etmiştir.');
    addQ(1, 3, 1, 'Yavuz Sultan Selim döneminde Memlük Devleti\'ne son verilerek Halifeliğin Osmanlı\'ya geçtiği savaşlar hangileridir?', 'Mercidabık ve Ridaniye Savaşları', 'Çaldıran ve Turnadağ', 'Otlukbeli ve Çaldıran', 'Mohaç ve Preveze', 'Varna ve II. Kosova', 'A', '1516 Mercidabık ve 1517 Ridaniye Savaşları ile Memlükler yıkılmış, halifelik Osmanlı\'ya geçmiştir.');
    addQ(1, 3, 1, 'Dünyanın en kısa süren meydan savaşı kabul edilen ve Macar Krallığı\'nı iki saatte yıkan zafer hangisidir?', 'Mohaç Meydan Muharebesi (1526)', 'Preveze Deniz Zaferi', 'Zigetvar Kuşatması', 'Çaldıran Savaşı', 'Kerne Muharebesi', 'A', 'Kanuni Sultan Süleyman 1526 Mohaç Zaferi ile Macaristan\'ı Osmanlı topraklarına katmıştır.');
    addQ(1, 3, 1, 'Akdeniz\'i Türk gölü haline getiren ve Haçlı donanmasını bozguna uğratan 1538 tarihli deniz zaferi hangisidir?', 'Preveze Deniz Zaferi', 'İnebahtı Savaşı', 'Cerbe Deniz Savaşı', 'Navarin Baskını', 'Çeşme Baskını', 'A', 'Barbaros Hayreddin Paşa komutasındaki Osmanlı donanması Andrea Doria komutasındaki Haçlıları Preveze\'de mağlup etmiştir.');

    // Level 2: Orta Düzey
    addQ(1, 3, 2, 'Osmanlı\'nın Balkanlar\'daki egemenliğini kesinleştiren ve Haçlıların Türkleri Balkanlar\'dan atma ümidini yok eden savaş hangisidir?', 'II. Kosova Savaşı (1448)', 'I. Kosova Savaşı', 'Varna Savaşı', 'Niğbolu Savaşı', 'Sırpsındığı Savaşı', 'A', 'II. Murad komutasındaki Osmanlı ordusu 1448 II. Kosova Zaferi ile Balkan hakimiyetini perçinlemiştir.');
    addQ(1, 3, 2, 'Yıldırım Bayezid\'e Haçlılara karşı kazandığı Niğbolu Zaferi (1396) sonrası Abbasi Halifesi tarafından hangi unvan verilmiştir?', 'Sultan-ı İklim-i Rum', 'Hadimü\'l-Haremeyn', 'Kayser-i Rum', 'Sahipkıran', 'Gazi-i Muazzam', 'A', 'Niğbolu Zaferi sonrası Abbasi Halifesi Yıldırım\'a "Sultan-ı İklim-i Rum" (Anadolu Diyarının Sultanı) unvanını vermiştir.');
    addQ(1, 3, 2, 'Anadolu Türk siyasi birliğini kesin olarak sağlayan, Turnadağ Savaşı (1515) ile Osmanlı\'ya bağlanan beylik hangisidir?', 'Dulkadiroğulları', 'Karamanoğulları', 'Candaroğulları', 'Germiyanoğulları', 'Hamitoğulları', 'A', 'Yavuz Sultan Selim Turnadağ Savaşı ile Dulkadiroğulları\'na son vererek Anadolu Türk birliğini kesinleştirmiştir.');
    addQ(1, 3, 2, 'Avusturya Arşidükünün protokolde Osmanlı sadrazamına denk sayıldığı 1533 tarihli antlaşma hangisidir?', 'İstanbul (İbrahim Paşa) Antlaşması', 'Zitvatorok Antlaşması', 'Vasvar Antlaşması', 'Karlofça Antlaşması', 'Pasarofça Antlaşması', 'A', '1533 İstanbul Antlaşması Osmanlı\'nın Avusturya üzerindeki siyasi üstünlüğünün zirvesidir.');
    addQ(1, 3, 2, 'Fatih Sultan Mehmed\'in deniz ticaretinde Venedik\'e karşı denge kurmak amacıyla ilk kez ticari ayrıcalık (kapitülasyon) verdiği devlet hangisidir?', 'Venedik', 'Fransa', 'İngiltere', 'Hollanda', 'Ceneviz', 'A', 'Fatih 1479\'da Venedik\'e ticari imtiyazlar ve İstanbul\'da Balyos (elçi) bulundurma hakkı vermiştir.');
