    addQ(1, 3, 2, 'Osmanlı Devleti\'nde Şehzadelerin sancaklara gönderilerek devlet tecrübesi kazanmasını zorunlu kılan ve kardeş katlini yasalaştıran kanunname hangisidir?', 'Kanunname-i Âli Osman', 'Ferman-ı Adalet', 'Tanzimat Fermanı', 'Sened-i İttifak', 'Mecelle', 'A', 'Fatih Sultan Mehmed Kanunname-i Âli Osman ile devlet teşkilatını ve veraset kurallarını kanunlaştırmıştır.');
    addQ(1, 3, 2, 'Osmanlı donanmasının tarihte ilk kez yakıldığı olay hangisidir?', 'İnebahtı Deniz Savaşı (1571)', 'Çeşme Baskını', 'Navarin Baskını', 'Sinop Baskını', 'Preveze', 'A', 'Kıbrıs\'ın fethi sonrası Haçlı donanması 1571 İnebahtı\'da Osmanlı donanmasını yakmıştır.');
    addQ(1, 3, 2, 'II. Bayezid döneminde yaşanan ve Osmanlı\'nın Batı seferlerinin duraksamasına, iç sorunun dış soruna dönüşmesine neden olan olay nedir?', 'Cem Sultan Olayı', 'Şahkulu İsyanı', 'Babazünnun İsyanı', 'Bozoklu Celal İsyanı', 'Kabakçı Mustafa İsyanı', 'A', 'Cem Sultan Rodos Şövalyelerine ve Papalığa sığınarak olayı uluslararası bir krize dönüştürmüştür.');
    addQ(1, 3, 2, 'Safevi Devleti (İran) ile Yavuz Sultan Selim arasında Şiilik propagandasını engellemek amacıyla yapılan 1514 tarihli savaş hangisidir?', 'Çaldıran Savaşı', 'Turnadağ Savaşı', 'Otlukbeli Savaşı', 'Ridaniye Savaşı', 'Kasr-ı Şirin', 'A', 'Yavuz 1514 Çaldıran Zaferi ile Şah İsmail\'i mağlup etmiş ve Doğu Anadolu güvenliğini sağlamıştır.');

    // Level 3: Zor & Detay
    addQ(1, 3, 3, 'Osmanlı\'nın 1533 İstanbul Antlaşması ile Avusturya\'ya kurduğu diplomatik üstünlüğü kaybettiği ve padişah ile kayserin denk sayıldığı 1606 tarihli antlaşma hangisidir?', 'Zitvatorok Antlaşması', 'Vasvar Antlaşması', 'Bucaş Antlaşması', 'Karlofça Antlaşması', 'Hotin Antlaşması', 'A', '1606 Zitvatorok Antlaşması ile Avusturya kralı Osmanlı padişahına denk sayılmış, protokol üstünlüğü bitmiştir.');
    addQ(1, 3, 3, 'Osmanlı Devleti\'nin Batı\'da en geniş sınırlara ulaştığı 1672 tarihli antlaşma hangisidir?', 'Bucaş Antlaşması', 'Karlofça Antlaşması', 'Zitvatorok Antlaşması', 'Hotin Antlaşması', 'Ferhat Paşa Antlaşması', 'A', 'Lehistan ile imzalanan Bucaş Antlaşması ile Podolya ve Kamaniçe alınmış, Batı\'da en geniş sınıra ulaşılmıştır.');
    addQ(1, 3, 3, 'Osmanlı Devleti\'nin Doğu\'da en geniş sınırlara ulaştığı (Azerbaycan, Gürcistan, Dağıstan) 1590 tarihli antlaşma hangisidir?', 'Ferhat Paşa Antlaşması', 'Kasr-ı Şirin Antlaşması', 'Nasuh Paşa Antlaşması', 'Serav Antlaşması', 'Amasya Antlaşması', 'A', 'III. Murad döneminde İran ile imzalanan Ferhat Paşa Antlaşması ile Doğu\'da en geniş sınıra ulaşılmıştır.');
    addQ(1, 3, 3, 'Günümüz Türkiye-İran sınırını büyük ölçüde belirleyen ve Zagros Dağları\'nı sınır kabul eden 1639 tarihli antlaşma hangisidir?', 'Kasr-ı Şirin Antlaşması', 'Ferhat Paşa Antlaşması', 'Nasuh Paşa Antlaşması', 'Ahmet Paşa Antlaşması', 'Kerden Antlaşması', 'A', 'IV. Murad\'ın Bağdat fethi sonrası imzalanan Kasr-ı Şirin Antlaşması bugünkü sınırın temelidir.');
    addQ(1, 3, 3, 'Osmanlı Devleti\'nin büyük çapta toprak kaybettiği ve Orta Avrupa egemenliğinin sona erdiği ilk antlaşma hangisidir?', 'Karlofça Antlaşması (1699)', 'Pasarofça Antlaşması', 'Küçük Kaynarca Antlaşması', 'Yaş Antlaşması', 'Belgrad Antlaşması', 'A', '1699 Karlofça Antlaşması ile Osmanlı ilk kez büyük çapta toprak kaybetmiş ve Gerileme Dönemi başlamıştır.');
    addQ(1, 3, 3, 'Osmanlı Devleti\'nde Şeyhülislam\'ın yetkilerini kısıtlayan ve ilk bütçeyi hazırlayan Tarhuncu Ahmet Paşa hangi dönem sadrazamıdır?', 'XVII. Yüzyıl (Duraklama)', 'Lale Devri', 'Tanzimat Dönemi', 'Yükselme Dönemi', 'II. Meşrutiyet', 'A', 'Tarhuncu Ahmet Paşa IV. Mehmed döneminde denk bütçe hazırlayan ilk devlet adamıdır.');
    addQ(1, 3, 3, 'Genç Osman\'ın (II. Osman) Hotin Seferi sırasında yeniçerilerin disiplinsizliğini görerek hangi kurumu kaldırmayı planlaması canına mal olmuştur?', 'Yeniçeri Ocağı', 'Sipahi Ocağı', 'Enderun', 'Divan-ı Hümayun', 'Kapıkulu Süvarileri', 'A', 'Genç Osman yeniçerileri kaldırmak istediği için yeniçeriler tarafından Yedikule zindanlarında katledilmiştir.');
    addQ(1, 3, 3, 'Osmanlı Devleti\'nin Lale Devri\'ne girmesine neden olan ve Batı\'nın üstünlüğünün kabul edildiği 1718 antlaşması hangisidir?', 'Pasarofça Antlaşması', 'Karlofça Antlaşması', 'Belgrad Antlaşması', 'Küçük Kaynarca Antlaşması', 'Prut Antlaşması', 'A', '1718 Pasarofça Antlaşması ile Osmanlı savunma politikasına geçmiş ve Lale Devri başlamıştır.');
    addQ(1, 3, 3, 'Kırım\'ın bağımsız olduğu ve Osmanlı\'nın ilk kez Müslüman bir toprağı kaybettiği 1774 tarihli antlaşma hangisidir?', 'Küçük Kaynarca Antlaşması', 'Yaş Antlaşması', 'Aynalıkavak Tenkihnamesi', 'Bükreş Antlaşması', 'Edirne Antlaşması', 'A', 'Küçük Kaynarca ile Kırım bağımsız olmuş, Karadeniz Türk gölü olmaktan çıkmış, Rusya\'ya kapitülasyon ve tazminat verilmiştir.');
    addQ(1, 3, 3, 'Kırım\'ın Rusya\'ya ait olduğunu Osmanlı\'nın resmen kabul ettiği ve Dağılma Dönemi\'nin başlangıcı sayılan 1792 antlaşması hangisidir?', 'Yaş Antlaşması', 'Küçük Kaynarca Antlaşması', 'Bükreş Antlaşması', 'Edirne Antlaşması', 'Hünkar İskelesi Antlaşması', 'A', '1792 Yaş Antlaşması ile Kırım kesin olarak Rus toprağı kabul edilmiştir.');

