    // Level 1: Temel Teşkilat
    addQ(1, 4, 1, 'Osmanlı Devleti\'nde padişahtan sonra en yetkili kişi olan ve padişahın mührünü taşıyan devlet adamı kimdir?', 'Sadrazam (Veziriazam)', 'Şeyhülislam', 'Kazasker', 'Defterdar', 'Kaptanıderya', 'A', 'Sadrazam padişahın mutlak vekilidir ve serdar-ı ekrem sıfatıyla orduya komuta eder.');
    addQ(1, 4, 1, 'Osmanlı Devleti\'nde adalet, eğitim ve kadı-müderris tayinlerinden sorumlu Divan üyesi kimdir?', 'Kazasker (Kadıasker)', 'Nişancı', 'Defterdar', 'Reisülküttab', 'Şeyhülislam', 'A', 'Kazasker adalet ve eğitim işlerinden sorumlu olup İlmiye sınıfının en üst divan temsilcisidir.');
    addQ(1, 4, 1, 'Devletin gelir ve giderlerini hesaplayan, bütçeyi hazırlayan maliye sorumlusu Divan üyesi kimdir?', 'Defterdar', 'Nişancı', 'Sadrazam', 'Yeniçeri Ağası', 'Müneccimbaşı', 'A', 'Defterdar Kalemiye sınıfına mensup maliye başıdır.');
    addQ(1, 4, 1, 'Padişah fermanlarına tuğra çeken, fethedilen toprakları tahrir defterine kaydeden görevli kimdir?', 'Nişancı', 'Reisülküttab', 'Kazasker', 'Çavuşbaşı', 'Kapıcılar Koğuşu', 'A', 'Nişancı tahrir kayıtlarını tutar ve örfi hukukun uzmanıdır.');
    addQ(1, 4, 1, 'Osmanlı\'da gayrimüslim çocukların devşirilerek saray bürokrasisinde veya Yeniçeri Ocağı\'nda istihdam edildiği saray okulu hangisidir?', 'Enderun', 'Birun', 'Harem', 'Medrese', 'Darülfünun', 'A', 'Enderun sarayın iç bölümünde üst düzey yönetici yetiştiren mekteptir.');
    addQ(1, 4, 1, 'Tımar sistemi kapsamında dirlik sahiplerinin beslemekle yükümlü olduğu atlı askerlere ne ad verilirdi?', 'Cebelü', 'Yeniçeri', 'Levent', 'Akıncı', 'Humbaracı', 'A', 'Dirlik sahipleri gelirlerine göre Cebelü denilen zırhlı atlı asker beslemek zorundaydı.');
    addQ(1, 4, 1, 'Osmanlı\'da Şeyhülislam\'ın bir kararın İslam dinine uygun olup olmadığını belirten yazılı onayına ne denir?', 'Fetva', 'Ferman', 'Berat', 'Hatt-ı Hümayun', 'Adaletname', 'A', 'Şeyhülislam fetva makamıdır.');
    addQ(1, 4, 1, 'Osmanlı\'da esnaf ve zanaatkârların bir araya geldiği, kalite ve narh (fiyat) kontrolü yapan meslek teşkilatına ne denir?', 'Lonca Teşkilatı', 'İltizam', 'Ayanlık', 'Düyun-ı Umumiye', 'Reaya', 'A', 'Ahiliğin devamı niteliğindeki Loncalar esnaf dayanışmasını ve üretim kontrolünü sağlamıştır.');
    addQ(1, 4, 1, 'Yeniçeri askerlerinin üç ayda bir aldıkları maaşa ne ad verilirdi?', 'Ulufe', 'Cülus', 'Bahşiş', 'Dirlik', 'İkta', 'A', 'Ulufe üç ayda bir dağıtılan maaş, Cülus ise tahta geçişte ödenen bahşiştir.');
    addQ(1, 4, 1, 'Osmanlı Devleti\'nde halkın devlete ödediği ürün üzerinden alınan 1/10 oranındaki şeri vergiye ne denir?', 'Öşür (Aşar)', 'Haraç', 'Cizye', 'Avarız', 'Ağnam', 'A', 'Müslümanlardan öşür, gayrimüslimlerden haraç ve askerlik karşılığı cizye alınırdı.');

    // Level 2: Orta Düzey
